import json
with open('/app/resources/treasury_bulletin_1991_09.json', 'r') as f:
    data = json.load(f)

# Print the keys at the top level
print('Top level keys:', list(data.keys()))
print()

# Look for any table that might have saving rate data
# Search for tables with years or saving
def find_tables(obj, path='', depth=0, max_depth=10):
    if depth > max_depth:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, list) and len(v) > 0:
                if isinstance(v[0], dict):
                    # Check if it looks like a table with years
                    first_keys = list(v[0].keys()) if v else []
                    print(f'{path}.{k}: list of {len(v)} dicts, keys: {first_keys[:5]}')
                    # Check for year-like keys
                    for vk in first_keys:
                        if '19' in str(vk) or 'year' in str(vk).lower() or 'saving' in str(vk).lower():
                            print(f'  -> Possible year/saving column: {vk}')
                find_tables(v, f'{path}.{k}', depth+1)
            elif isinstance(v, dict):
                find_tables(v, f'{path}.{k}', depth+1)

find_tables(data)
